def glyph(code: int) -> bytes:
    if not 32 <= code <= 127:
        raise ValueError(f"font covers 32-127, not {code}")
    o = 8 * (code - 32)
    return FONT[o : o + 8]


def rows(code: int) -> list[str]:
    out = []
    for b in glyph(code):
        out.append("".join("#" if b & (0x80 >> c) else "." for c in range(8)))
    return out
